insert into public.food_sources(id,key,name,base_url) values ('10000000-0000-0000-0000-000000000001','internal','Internal reviewed catalog',null),('10000000-0000-0000-0000-000000000002','usda_fdc','USDA FoodData Central','https://api.nal.usda.gov'),('10000000-0000-0000-0000-000000000003','open_food_facts','Open Food Facts','https://world.openfoodfacts.org');
insert into public.nutrient_categories(id,key,name,sort_order) values ('20000000-0000-0000-0000-000000000001','energy_macros','Energy and macronutrients',1),('20000000-0000-0000-0000-000000000002','vitamins','Vitamins',2),('20000000-0000-0000-0000-000000000003','minerals','Minerals',3);
insert into public.nutrient_units(id,symbol,name) values ('30000000-0000-0000-0000-000000000001','kcal','kilocalorie'),('30000000-0000-0000-0000-000000000002','g','gram'),('30000000-0000-0000-0000-000000000003','mg','milligram'),('30000000-0000-0000-0000-000000000004','µg','microgram');
insert into public.nutrients(id,key,name,category_id,default_unit_id,is_core) values
('40000000-0000-0000-0000-000000000001','energy_kcal','Calories','20000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000001',true),('40000000-0000-0000-0000-000000000002','protein','Protein','20000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000002',true),('40000000-0000-0000-0000-000000000003','carbohydrate','Carbohydrate','20000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000002',true),('40000000-0000-0000-0000-000000000004','fat','Total fat','20000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000002',true),('40000000-0000-0000-0000-000000000005','fiber','Fiber','20000000-0000-0000-0000-000000000001','30000000-0000-0000-0000-000000000002',true),('40000000-0000-0000-0000-000000000006','sodium','Sodium','20000000-0000-0000-0000-000000000003','30000000-0000-0000-0000-000000000003',true);
insert into public.foods(id,name,brand,description,food_type,is_public,is_verified) values
('50000000-0000-0000-0000-000000000001','Original Macaroni & Cheese Dinner','Kraft','Demo branded prepared macaroni and cheese','branded',true,true),('50000000-0000-0000-0000-000000000002','Deluxe Original Cheddar Macaroni & Cheese','Kraft','Demo branded deluxe macaroni and cheese','branded',true,true),('50000000-0000-0000-0000-000000000003','Easy Mac Original Macaroni & Cheese Cup','Kraft','Demo single-serve cup','branded',true,true),('50000000-0000-0000-0000-000000000004','Macaroni and cheese, prepared','Generic','Demo generic prepared food','generic',true,true),('50000000-0000-0000-0000-000000000005','Apple, raw, with skin',null,'Demo generic fruit','generic',true,true),('50000000-0000-0000-0000-000000000006','White mushrooms, raw',null,'Demo generic mushroom','generic',true,true);
insert into public.food_versions(id,food_id,version,source_id,provider_record_id,data_completeness,contains_projections) select ('60000000-0000-0000-0000-'||right(id::text,12))::uuid,id,1,'10000000-0000-0000-0000-000000000001','demo-'||right(id::text,3),case when brand='Kraft' then 62 else 85 end,false from public.foods where id::text like '50000000%';
insert into public.food_servings(food_version_id,label,amount,unit,gram_weight,is_default) select id,case when provider_record_id like '%001' then '1 cup prepared' when provider_record_id like '%002' then '1 cup prepared' when provider_record_id like '%003' then '1 cup' else '100 g' end,1,'serving',case when provider_record_id like '%001' then 180 when provider_record_id like '%002' then 190 when provider_record_id like '%003' then 58 else 100 end,true from public.food_versions;
insert into public.food_version_nutrients(food_version_id,nutrient_id,amount_per_100g,unit_id,classification) select v.id,n.id,case n.key when 'energy_kcal' then case f.id when '50000000-0000-0000-0000-000000000001' then 205 when '50000000-0000-0000-0000-000000000002' then 220 when '50000000-0000-0000-0000-000000000003' then 365 when '50000000-0000-0000-0000-000000000004' then 164 when '50000000-0000-0000-0000-000000000005' then 52 else 22 end when 'protein' then 7 when 'carbohydrate' then 28 when 'fat' then 7 when 'fiber' then 1.5 when 'sodium' then 430 end,n.default_unit_id,'provider_reported' from public.food_versions v join public.foods f on f.id=v.food_id cross join public.nutrients n;
insert into public.food_popularity(food_id,total_selections,unique_users,recent_selections,score) select id,case when brand='Kraft' then 500 else 200 end,100,50,case when brand='Kraft' then 90 else 70 end from public.foods;
